import Foundation

/// Coarse land/sea grid of the Earth: 360 x 180 one-degree cells, row 0 at 90°N,
/// column 0 at 180°W, packed one bit per cell (1 = land).
enum LandMask {
    static let bits: [UInt8] = Array(Data(base64Encoded: data)!)
    static func isLand(lat: Double, lon: Double) -> Bool {
        let row = min(179, max(0, Int(90 - lat)))
        let col = (Int(floor(lon + 180)) % 360 + 360) % 360
        let i = row * 360 + col
        return bits[i >> 3] & (0x80 >> UInt8(i & 7)) != 0
    }
    private static let data = ""
}
